function route(){const id=(location.hash||'#accueil').slice(1).split('?')[0];document.querySelectorAll('.screen').forEach(x=>x.classList.remove('active'));(document.getElementById(id)||document.getElementById('accueil')).classList.add('active');window.scrollTo(0,0)}
function renderDays(){dayList.innerHTML=days.map(d=>`<div class="dayitem ${d.pending?'pending':''}" data-day="${d.n}"><div class="daynum">${d.n}</div><div><b>${d.title}</b><small>${d.date}${d.pending?' · à compléter':''}</small></div></div>`).join('');dayList.onclick=e=>{const x=e.target.closest('[data-day]');if(x){renderDay(+x.dataset.day);location.hash='day'}}}
function renderDay(n){const d=days.find(x=>x.n===n);const isRide=d.facts&&d.facts.some(f=>f[0]==='Distance');const shortDate=d.date.replace(/^(Lundi|Mardi|Mercredi|Jeudi|Vendredi|Samedi|Dimanche)\s+/,'').replace(/\s+2026$/,'');dayContent.innerHTML=`${isRide?`<p class="eyebrow">${shortDate}</p><h1>${shortDate} — ${d.title}</h1>`:`<p class="eyebrow">JOUR ${d.n}</p><h1>${d.title}</h1><p class="muted">${d.date}</p>`}${d.pending?'<div class="panel warning"><b>Étape provisoire</b><p>Le découpage, la distance et l’hébergement restent à confirmer.</p></div>':''}<div class="spirit"><small>L’ESPRIT DE LA JOURNÉE</small><strong>${d.spirit}</strong></div><div class="facts">${d.facts.map(f=>`<div class="fact"><small>${f[0]}</small><b>${f[1]}</b></div>`).join('')}</div><h2>Programme</h2><div class="timeline">${d.stops.map(s=>`<div class="stop"><b>${s[0]}</b><p>${s[1]}</p>${s[2]?`<div class="activity-links">${s[2].map(l=>`<a target="_blank" rel="noopener" href="${l[1]}">${l[0]}</a>`).join('')}</div>`:''}</div>`).join('')}</div>${d.actions?`<div class="daylinks">${d.actions.map(a=>`<button class="btn route-action" data-action="${a[1]}" data-file="${a[2]}">${a[0]}</button>`).join('')}</div>`:''}${d.links?`<div class="daylinks">${d.links.map(l=>`<a class="btn" target="_blank" rel="noopener" href="${l[1]}">${l[0]}</a>`).join('')}</div>`:''}`}

async function shareGpx(fileName){
  try{
    const response=await fetch(fileName,{cache:'no-store'});
    if(!response.ok)throw new Error('Fichier GPX introuvable');
    const blob=await response.blob();
    const file=new File([blob],fileName,{type:'application/gpx+xml'});
    if(navigator.canShare&&navigator.canShare({files:[file]})){
      await navigator.share({
        files:[file],
        title:fileName.includes('jour-21')?'Jour 21 — Montélimar → Orange':fileName.includes('jour-20')?'Jour 20 — Tain-l’Hermitage → Montélimar':fileName.includes('jour-17')?'Jour 17 — Belleville-en-Beaujolais → Givors':fileName.includes('jour-16')?'Jour 16 — Tournus → Belleville-en-Beaujolais':fileName.includes('jour-15')?'Jour 15 — Chagny → Tournus':fileName.includes('jour-14')?'Jour 14 — Marsannay-la-Côte → Chagny':fileName.includes('jour-13')?'Jour 13 — Boucle dans les vignobles':fileName.includes('jour-11')?'Jour 11 — Dole → Marsannay-la-Côte':fileName.includes('jour-10')?'Jour 10 — Besançon → Dole':fileName.includes('jour-09')?'Jour 9 — L’Isle-sur-le-Doubs → Besançon':fileName.includes('jour-08')?'Jour 8 — Aspach-le-Bas → L’Isle-sur-le-Doubs':fileName.includes('jour-07')?'Jour 7 — Colmar → Aspach-le-Bas':fileName.includes('jour-06')?'Jour 6 — Barr → Colmar':fileName.includes('jour-05')?'Jour 5 — Strasbourg → Barr':'Parcours Gare de Strasbourg → Airbnb',
        text:'Ouvrir ce parcours dans RideWithGPS'
      });
    }else{
      const a=document.createElement('a');
      a.href=URL.createObjectURL(blob);
      a.download=fileName;
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(()=>URL.revokeObjectURL(a.href),1000);
      alert('Le fichier GPX a été téléchargé. Ouvrez-le depuis Fichiers, puis choisissez RideWithGPS.');
    }
  }catch(err){
    if(err&&err.name==='AbortError')return;
    alert('Impossible d’ouvrir le GPX automatiquement. Utilisez le lien MapQuest ou réessayez.');
  }
}
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-action="share-gpx"]');
  if(b){e.preventDefault();shareGpx(b.dataset.file);}
});

function loadNotes(){const a=JSON.parse(localStorage.getItem('france2026notes')||'[]');notes.innerHTML=a.map((n,i)=>`<div class="noteitem"><button data-del="${i}">Supprimer</button><b>${escapeHtml(n.t)}</b><p>${escapeHtml(n.x).replace(/\n/g,'<br>')}</p></div>`).join('')||'<p class="muted">Aucune note enregistrée.</p>'}
function escapeHtml(s){return s.replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
saveNote.onclick=()=>{if(!noteText.value.trim())return;const a=JSON.parse(localStorage.getItem('france2026notes')||'[]');a.unshift({t:noteTitle.value.trim()||new Date().toLocaleDateString('fr-CA'),x:noteText.value.trim()});localStorage.setItem('france2026notes',JSON.stringify(a));noteTitle.value=noteText.value='';loadNotes()};notes.onclick=e=>{if(e.target.dataset.del!==undefined){const a=JSON.parse(localStorage.getItem('france2026notes')||'[]');a.splice(+e.target.dataset.del,1);localStorage.setItem('france2026notes',JSON.stringify(a));loadNotes()}};document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>location.hash=b.dataset.go);window.addEventListener('hashchange',route);renderDays();loadNotes();route();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js?v=4.0').then(r=>r.update());
